// ─── File: EventOrderingDemo.java ───
// Runnable demo: wall-clock misordering vs Lamport and HLC causal ordering.

import java.util.*;
import java.util.logging.*;

public class EventOrderingDemo {

    private static final Logger log = Logger.getLogger("ordering");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Node A clock runs +3000ms fast; Node B runs -2000ms slow (skew).
        LedgerNode nodeA = new LedgerNode("DepositSvc", +3000);
        LedgerNode nodeB = new LedgerNode("WithdrawalSvc", -2000);

        // Rajesh deposits on A (cause), which triggers a withdrawal on B (effect).
        LedgerEvent deposit = nodeA.localEvent("DEPOSIT", 100000);
        LedgerEvent withdrawal = nodeB.onMessageThenLocalEvent(deposit, "WITHDRAWAL", 50000);

        // WRONG: sort by wall clock → effect appears before cause because B's clock is slow.
        List<LedgerEvent> byWall = new ArrayList<>(List.of(deposit, withdrawal));
        byWall.sort(Comparator.comparingLong(e -> e.wallClock));
        log.severe("Order by WALL CLOCK (wrong): " + byWall);

        // RIGHT: sort by Lamport → cause always precedes effect.
        List<LedgerEvent> byLamport = new ArrayList<>(List.of(deposit, withdrawal));
        byLamport.sort(Comparator.comparingLong(e -> e.lamport));
        log.info("Order by LAMPORT (correct): " + byLamport);

        // RIGHT + READABLE: HLC keeps causal order AND a meaningful time component.
        List<LedgerEvent> byHlc = new ArrayList<>(List.of(deposit, withdrawal));
        byHlc.sort(Comparator.<LedgerEvent>comparingLong(e -> e.hlcPhysical).thenComparingInt(e -> e.hlcLogical));
        log.info("Order by HLC (correct + readable): " + byHlc);
    }
}

// ─── model/LedgerEvent.java ───
class LedgerEvent {
    final String node; final String type; final long amount;
    final long wallClock; final long lamport; final long hlcPhysical; final int hlcLogical;
    LedgerEvent(String node, String type, long amount, long wallClock,
                long lamport, long hlcPhysical, int hlcLogical) {
            this.node = node;
            this.type = type
            this.amount = amount
            this.wallClock = wallClock;
            this.lamport = lamport;
            this.hlcPhysical = hlcPhysical
            this.hlcLogical = hlcLogical;
    }
    @Override public String toString() {
        return type + "(" + node + ", wall=" + wallClock + ", L=" + lamport
                + ", HLC=" + hlcPhysical + "." + hlcLogical + ")";
    }
}

// ─── clock/LamportClock.java ───
class LamportClock {
    private long counter = 0;
    long tickLocal() { return ++counter; }                  // local event
    long tickReceive(long received) {                        // on receive
        counter = Math.max(counter, received) + 1;
        return counter;
    }
    long current() { return counter; }
}

// ─── clock/HybridLogicalClock.java ───
class HybridLogicalClock {
    private long physical = 0; private int logical = 0;
    // local/send event
    long[] tickLocal(long wallNow) {
        long prevPhysical = physical;
        physical = Math.max(prevPhysical, wallNow);
        logical = (physical == prevPhysical) ? logical + 1 : 0;  // bump counter if time didn't advance
        return new long[]{physical, logical};
    }
    // receive event: merge with the message's HLC
    long[] tickReceive(long wallNow, long msgPhysical, int msgLogical) {
        long prevPhysical = physical;
        physical = Math.max(Math.max(prevPhysical, msgPhysical), wallNow);
        if (physical == prevPhysical && physical == msgPhysical) logical = Math.max(logical, msgLogical) + 1;
        else if (physical == prevPhysical) logical = logical + 1;
        else if (physical == msgPhysical) logical = msgLogical + 1;
        else logical = 0;
        return new long[]{physical, logical};
    }
}

// ─── node/LedgerNode.java ───
class LedgerNode {
    private static final Logger log = Logger.getLogger("ordering");
    private final String name; private final long skewMs;
    private final LamportClock lamport = new LamportClock();
    private final HybridLogicalClock hlc = new HybridLogicalClock();
        LedgerNode(String name, long skewMs) { this.name = name;
        this.skewMs = skewMs; }

    private long skewedWallClock() { return System.currentTimeMillis() + skewMs; } // simulate drift

    LedgerEvent localEvent(String type, long amount) {
        long wall = skewedWallClock();
        long l = lamport.tickLocal();
        long[] h = hlc.tickLocal(wall);
        LedgerEvent e = new LedgerEvent(name, type, amount, wall, l, h[0], (int) h[1]);
        log.fine(() -> "[" + name + "] local " + e);
        return e;
    }

    // Receive the causing event's clocks, then record this (effect) event.
    LedgerEvent onMessageThenLocalEvent(LedgerEvent cause, String type, long amount) {
        long wall = skewedWallClock();
        long l = lamport.tickReceive(cause.lamport);                 // Lamport merge
        long[] h = hlc.tickReceive(wall, cause.hlcPhysical, cause.hlcLogical); // HLC merge
        LedgerEvent e = new LedgerEvent(name, type, amount, wall, l, h[0], (int) h[1]);
        log.fine(() -> "[" + name + "] after receiving " + cause.type + " recorded " + e);
        return e;
    }
}

